static void z_t1474_destroy(z_t1474_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_OPENRESULT_TAG_OK:
            z_t77_free((z_t77_t*)u->data);
            free(u->data);
            break;
        case Z_OPENRESULT_TAG_ERR:
            z_t1475_destroy((z_t1475_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

